              :to="link.to"
              :isCollapsed="isSidebarCollapsed"
              class="mx-2 my-[1.5px]"
            />
          </nav>
        </CollapsibleSection>
      </div>
    </div>
    <div class="m-2 flex flex-col gap-1">
